{"packet_id":"D067-01","doc_id":"D067","jurisdiction":"NJ","category":"security_deposits","lifecycle":"enacted","title":"New Jersey Security Deposit Law","requirement":"A landlord may not hold a security deposit above one and one-half times one month's rent, may not raise it more than 10% a year, and must return it with interest within 30 days after the tenancy ends.","key_value":"1.5 months' rent; +10%/year increase cap; 30-day return","coverage_conditions":"Residential tenancies in New Jersey; a landlord need not take a deposit, but must follow the law if one is taken.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":null},"exemptions":"Seasonal use or rental of not more than 125 consecutive days by a person with a permanent residence elsewhere.","penalty":"Tenant may sue for double the amount wrongfully withheld plus court costs and reasonable attorney's fees.","effective_date":null,"citation":"N.J.S.A. 46:8-19 to 46:8-26","quoted_span":"The maximum-security deposit to be collected by the landlord cannot be more than one and one-half times one month’s rent ( N.J.S.A. 46:8-21.2 ). It can be less.","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D067-01","doc_id":"D067","jurisdiction":"NJ","category":"security_deposits","lifecycle":"enacted","title":"Safe Housing Act security deposit return after domestic-violence termination","requirement":"When a tenant ends a lease under the Safe Housing Act, the landlord must make the security deposit plus interest available within 15 business days and give written notice of pickup within three business days.","key_value":"15 business days","coverage_conditions":"Tenants who terminate a lease under the Safe Housing Act because of domestic violence; does not apply to transient or seasonal rentals.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":null},"exemptions":"Transient or seasonal rentals.","penalty":null,"effective_date":null,"citation":"N.J.S.A. 46:8-9.6","quoted_span":"Within 15 business days after the lease is terminated, the landlord shall make available the return of the tenant’s security deposit, plus any interest earned, to the tenant or the tenant’s agent.","interaction":null,"confidence":0.75,"conflict_flag":false,"conflict_note":null}
